const fill = (tpl, vars) => String(tpl || '').replace(/\{\{(\w+)\}\}/g, (m, k) =>
  vars[k] === undefined ? m : (typeof vars[k] === 'string' ? vars[k] : JSON.stringify(vars[k])));
const claudeText = (res) => (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
const parseJson = (text, label) => {
  const a = text.indexOf('{'), b = text.lastIndexOf('}');
  if (a < 0 || b < 0) throw new Error(label + ': no JSON in model output: ' + text.slice(0, 200));
  try { return JSON.parse(text.slice(a, b + 1)); } catch (e) { throw new Error(label + ': JSON parse failed: ' + e.message); }
};
const claudeBody = (p, vars, fallbackModel, overrides = {}) => ({
  model: p.model || fallbackModel,
  max_tokens: p.max_tokens || 4000,
  temperature: Number(overrides.temperature ?? p.temperature ?? 0.7),
  system: [{ type: 'text', text: fill(p.system, vars), cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: overrides.content || fill(p.user, vars) }],
});

// Handles both the first pass (claim payload) and the revise loop (from 'Attach Revision Feedback').
const inp = $input.first().json;
const claim = inp.revision ? inp.claim : inp;
const attempt = inp.revision ? inp.attempt : 1;
const feedback = inp.revision ? inp.feedback : '';
const { brief, page, characters, prompts } = claim;
const p = prompts && prompts.script_writer;
if (!p) throw new Error('No active prompt_versions row for script_writer');
const mode = (brief.speaker_mode || 'CHANG').toUpperCase();
const bible = characters
  .filter(c => mode === 'DUO' || c.slug === mode.toLowerCase())
  .map(c => c.bible_md).join('\n\n---\n\n');
if (!bible.trim()) throw new Error('Empty character bible for speaker_mode ' + mode);
const cta = (brief.brief && brief.brief.cta_keyword) || (page.cta_keywords || [])[0] || 'STRONG';
const vars = {
  CHARACTER_BIBLE: bible, BRIEF_JSON: brief.brief, PAGE_DNA_JSON: page.page_dna || {},
  EVIDENCE_INDEX: claim.evidence_index || '', HOOK_LIBRARY: claim.hook_library || [],
  RECENT_HOOKS: claim.recent_hooks || [], REVISION_FEEDBACK: feedback, CTA_KEYWORD: cta,
};
const body = claudeBody(p, vars, $env.MODEL_WRITER || 'claude-sonnet-5-5',
  { temperature: attempt > 1 ? 0.6 : (p.temperature ?? 0.9) });
return [{ json: { claim, attempt, cta, anthropic_body: body } }];

