// Deterministic bands (prompts/07_qa_vision_checker.md). Calibrate on ~100 human-labelled renders in week 1.
const pv = $('Parse Verdict').first().json;
const m = $('Worker: Deterministic QA').first().json.metrics || {};
const asm = $('Worker: Assemble Master (Remotion/ffmpeg)').first().json;
const v = parseJson(claudeText($input.first().json), 'qa_vision');
let det = 'pass'; const reasons = [];
const band = (name, val, passT, reviewT) => {
  if (val === null || val === undefined) return;
  if (passT(val)) return;
  if (reviewT(val)) { if (det === 'pass') det = 'review'; reasons.push(`${name}=${val} (review)`); }
  else { det = 'fail'; reasons.push(`${name}=${val} (fail)`); }
};
band('face_sim_median', m.face_sim_median, x => x >= 0.55, x => x >= 0.45);
band('face_sim_min', m.face_sim_min, x => x >= 0.40, x => x >= 0.32);
band('syncnet_conf', m.syncnet_conf, x => x >= 6.0, x => x >= 4.5);
band('syncnet_dist', m.syncnet_dist, x => x <= 8.0, x => x <= 9.0);
band('lufs', m.lufs_integrated, x => Math.abs(x + 14) <= 1, x => Math.abs(x + 14) <= 2);
band('true_peak_db', m.true_peak_db, x => x <= -1.0, x => x <= -0.3);
band('caption_cer', m.caption_cer, x => x <= 0.01 && !m.caption_number_mismatch, x => x <= 0.03 && !m.caption_number_mismatch);
band('black_freeze_s', Math.max(m.black_max_s || 0, m.freeze_max_s || 0), x => x <= 0.25, x => x <= 0.6);
if (m.spec_ok === false) { det = 'fail'; reasons.push('spec (res/fps/codec)'); }
if (m.c2pa_present === false) reasons.push('c2pa missing (re-sign)');
if (m.ai_tag_present === false) { det = 'fail'; reasons.push('D-02 AI corner tag missing'); }
if (m.duration_ok === false) { det = 'fail'; reasons.push('duration out of bounds'); }
const uq = $('Worker: Uniqueness Guard').first().json || {};
const uniqueOk = uq.allow !== false;
if (!uniqueOk) reasons.push('uniqueness: ' + (uq.reasons || []).join('; '));
if (m.c2pa_present === false && det === 'pass') det = 'review';
if (m.c2pa_trusted === false) reasons.push('c2pa untrusted (dev cert): no auto-publish');
const rank = { pass: 0, review: 1, fail: 2 };
const decision = [det, v.decision || 'review'].sort((a, b) => rank[b] - rank[a])[0];
const risk = (pv.judge && pv.judge.risk_tier) || 'green';
const trusted = pv.claim.page.auto_publish === true;
let route;
if (!uniqueOk) route = 'human';   // a duplicate isn't fixed by re-rendering the same script
else if (decision === 'fail') route = (pv.claim.brief.attempts || 1) < 3 ? 'regen' : 'human';
else if (decision === 'pass' && trusted && risk === 'green' && m.c2pa_trusted !== false && m.c2pa_present !== false) route = 'auto';
else route = 'approval';   // package now, post as draft, a human approves in the review app
if ((pv.judge || {}).judge_ok !== true && (route === 'auto' || route === 'approval')) { route = 'human'; reasons.push('mandatory LLM judge did not pass'); }  // defence in depth
const status = route === 'auto' ? 'approved' : route === 'approval' ? 'awaiting_approval' : 'rejected';
return [{ json: { route, decision, reasons, status, vision: v, metrics: m, uniqueness: uq, rerender_shots: v.rerender_shots || [],
  video_row: { brief_id: pv.claim.brief.id, script_id: pv.script_id, page_id: pv.claim.page.id,
    master_asset_id: asm.asset_id || null, duration_s: asm.duration_s || null, qa_decision: decision,
    qa_metrics: m, qa_vision: v, status } } }];

