// SAFETY_RULES.md checker pass 2: final captions + burned-in text + ASR transcript of the rendered master.
const pv = $('Parse Verdict').first().json;
const pk = parseJson(claudeText($input.first().json), 'caption_writer');
const asm = $('Worker: Assemble Master (Remotion/ffmpeg)').first().json;
const dna = pv.claim.page.page_dna || {};
const texts = [
  ['transcript', asm.transcript || ''],
  ['ig', (pk.instagram && pk.instagram.caption) || ''], ['tt', (pk.tiktok && pk.tiktok.caption) || ''],
  ['yt', ((pk.youtube && pk.youtube.title) || '') + ' ' + ((pk.youtube && pk.youtube.description) || '')],
  ['fb', (pk.facebook && pk.facebook.caption) || ''], ['threads', (pk.threads && pk.threads.text) || ''], ['x', (pk.x && pk.x.text) || ''],
