const issues = [];
for (const [where, t] of texts) for (const bc of pv.claim.blocked_claims || []) {
  if (!bc.regex || bc.severity !== 'block') continue;
  let re; try { re = new RegExp(bc.regex, 'i'); } catch (e) { continue; }
  const m = matchAny(re, t); if (m) issues.push({ where, id: bc.id, match: m[0] });
}
const footer = (dna.caption_footer || '').trim();
for (const [where, t] of texts.filter(([w]) => ['ig', 'tt', 'yt', 'fb'].includes(w)))
  if (footer && !t.includes(footer)) issues.push({ where, id: 'S7-footer', match: 'required footer missing' });
if (pk.tiktok && pk.tiktok.is_aigc !== true) issues.push({ where: 'tt', id: 'AIGC', match: 'is_aigc must be true' });
if (pk.youtube && pk.youtube.contains_synthetic_media !== true) issues.push({ where: 'yt', id: 'AS', match: 'containsSyntheticMedia must be true' });
if (pk.x && /https?:\/\//.test(pk.x.text || '')) issues.push({ where: 'x', id: 'X-link', match: 'no links in X body' });
