// Slot times in page timezone + deterministic jitter + per-platform offsets; drafts unless route=auto.
const pv = $('Parse Verdict').first().json;
const route = $('Decide QA Route').first().json.route;
const pkw = $('Worker: Package + Pass 2').first().json;   // normalised packaging + UTM links
const pk = pkw.packaging;
const links = pkw.links || {};
const SRC = { instagram: 'ig', tiktok: 'tt', youtube: 'yt', facebook: 'fb', threads: 'threads', x: 'x' };
const video = $('Save Video + QA').first().json;
const rendered = Object.fromEntries(($input.first().json.variants || []).map(v => [v.platform, v]));
const b = pv.claim.brief, page = pv.claim.page;
const SLOTS = ['07:10', '09:35', '11:50', '13:25', '15:40', '17:15', '19:05', '20:30', '21:45'];
const OFFSET_MIN = { instagram: 0, tiktok: 25, youtube: 50, facebook: 75, threads: 10, x: 35 };
let seed = 0; for (const ch of String(b.id)) seed = (seed * 31 + ch.charCodeAt(0)) % 9973;
const jitter = (seed % 19) - 9; // ±9 min, stable per brief
const [hh, mm] = SLOTS[Math.min(b.slot_index, SLOTS.length - 1)].split(':').map(Number);
const base = DateTime.fromISO(b.target_date, { zone: page.timezone || 'America/New_York' }).set({ hour: hh, minute: mm });
const posts = [];
for (const acct of pv.claim.accounts || []) {
  const pl = acct.platform, pack = pk[pl] || {};
  let isTrial = false;
  if (b.slot_index >= (acct.daily_post_target || 3)) {
    if (pl === 'instagram' && pack.trial_reel_eligible) isTrial = true;   // extra IG slots run as Trial Reels
    else continue;                                                         // respect ramp target
  }
  const textOnly = (pl === 'threads' || pl === 'x') && !pack.attach_video;
  const when = base.plus({ minutes: OFFSET_MIN[pl] + jitter });
  const utm = { utm_source: SRC[pl] || pl, utm_medium: 'organic_short', utm_campaign: page.slug, utm_content: `${String(b.id).slice(0, 8)}-${SRC[pl] || pl}`, link: links[pl] || null };  // PIPELINE §7.1
  posts.push({
    platform: pl, page_account_id: acct.id, asset_id: textOnly ? null : ((rendered[pl] || {}).asset_id || null),
    packaging: pack, caption: pack.caption || pack.description || pack.text || '', title: pack.title || null,
    hashtags: pack.hashtags || pack.tags || [], on_screen_hook: pack.on_screen_hook || null,
    kind: textOnly ? 'text' : 'video', body_text: textOnly ? pack.text : null,
    scheduled_at: when.toUTC().toISO(), is_trial_reel: isTrial, utm,
    status: route === 'auto' ? 'scheduled' : 'draft',
