}
return [{ json: { payload: { video_id: video.id, posts }, needs_approval: route !== 'auto', n: posts.length } }];

const req = $input.first().json;
const secret = (req.headers || {})['x-review-secret'];
if (!secret || secret !== $env.REVIEW_WEBHOOK_SECRET) throw new Error('Invalid review secret');
const b = req.body || {};
if (!['approved', 'rejected', 'fix_requested'].includes(b.decision)) throw new Error('Bad decision: ' + b.decision);
if (!b.video_id) throw new Error('video_id required');
return [{ json: { p_video_id: b.video_id, p_decision: b.decision, p_reviewer: b.reviewer || 'unknown', p_notes: b.notes || null } }];

const d = $('Loop Over Posts').first().json;          // {post, account, variant, asset_url, page_slug}
const tok = $input.first().json || {};
if (tok.error) throw new Error('Token error for account ' + d.account.id + ': ' + tok.error);
const v = d.variant || {}, pk = v.packaging || {};
const utm = d.post.utm || {};
const route = d.account.publisher === 'official' && ['instagram', 'tiktok', 'youtube'].includes(d.post.platform) ? d.post.platform : 'other';
const caption = d.post.kind === 'text' ? (d.post.body_text || '') : (v.caption || '') + (v.hashtags && v.hashtags.length && !/#\w/.test(v.caption || '') ? '\n' + v.hashtags.join(' ') : '');
return [{ json: {
  route, post_id: d.post.id, platform: d.post.platform, kind: d.post.kind, is_trial_reel: d.post.is_trial_reel,
  video_url: d.asset_url, caption, title: v.title || (pk.title || ''), description: pk.description || caption,
  tags: pk.tags || [], access_token: tok.access_token, user_id: tok.user_id || d.account.external_account_id,
  uploadpost_user: d.account.publisher_ref, utm } }];

const req = $('Prepare Publish Request').first().json;
const r = $input.first().json || {};
let ok = false, id = null, link = null, err = null;
if (r.error && typeof r.error === 'object' && r.error.code && r.error.code !== 'ok') err = JSON.stringify(r.error);
else if (typeof r.error === 'string' || (r.error && r.error.message)) err = typeof r.error === 'string' ? r.error : r.error.message;
switch (req.platform) {
  case 'instagram': id = r.id || null; ok = !!id && !err; break;
  case 'tiktok': id = (r.data && r.data.publish_id) || null; ok = !!id && (!r.error || r.error.code === 'ok'); break;
  case 'youtube': id = r.id || null; ok = !!id && !err; link = id ? 'https://youtube.com/shorts/' + id : null; break;
  default: ok = r.success === true || r.status === 'success'; id = r.request_id || r.id || JSON.stringify(r.results || {}).slice(0, 200);
